import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 호봉 1단계당 인상액 (산식 미정)
const STEP_AMOUNT = 100000;
// 가정: 인건비 = 예상 총 지급액 x (1 + 사업주 부담률)
const EMPLOYER_BURDEN_RATE = 0.1;

const WITH_LATEST = `
  WITH latest AS (
    SELECT DISTINCT ON (p.employee_id)
      p.payroll_id, p.employee_id, p.total_payment_amount,
      p.total_deduction_amount, p.net_pay_amount
    FROM payroll p
    JOIN payday d ON d.payday_id = p.payday_id
    ORDER BY p.employee_id, d.pay_date DESC, p.payroll_id DESC
  )
`;

const FROM_WHERE = `
  FROM employee e
  JOIN latest l ON l.employee_id = e.employee_id
  WHERE (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))
    AND (CAST(:employeeId AS bigint) IS NULL OR e.employee_id = CAST(:employeeId AS bigint))
`;

function invalid(message: string): ApiError {
  return new ApiError(422, 'INVALID_SIMULATION_CONDITION', message);
}

function optionalNumber(value: unknown, label: string, integer: boolean): number | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw invalid(label + ' 값이 올바르지 않습니다.');
  }
  if (integer && !Number.isInteger(value)) {
    throw invalid(label + ' 값은 정수여야 합니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr02118Controller {
  @Post('/payroll-simulations/run')
  @HttpCode(200)
  async runPayrollSimulation(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const query = checks.queryOf(req.query);
    const raiseRate = optionalNumber(data['raiseRate'], '급여 인상률', false);
    const stepChange = optionalNumber(data['stepChange'], '호봉 변경 단계 수', true);
    const departmentId = optionalNumber(data['departmentId'], '대상 조직', true);
    const employeeId = optionalNumber(data['employeeId'], '대상 임직원', true);
    // 가정: 인상률과 호봉 변경 중 하나는 있어야 조건이 있는 것으로 본다
    if (raiseRate === null && stepChange === null) {
      throw invalid('급여 인상률 또는 호봉 변경 단계 수를 입력하세요.');
    }
    const pageNo = Math.max(0, Number(query['page'] ?? 0) || 0);
    const size = Math.min(200, Math.max(1, Number(query['size'] ?? 20) || 20));
    return transaction(async (db) => {
      const params = {
        raiseRate: raiseRate ?? 0,
        stepChange: stepChange ?? 0,
        stepAmount: STEP_AMOUNT,
        burdenRate: EMPLOYER_BURDEN_RATE,
        departmentId: departmentId,
        employeeId: employeeId,
        limit: size,
        offset: pageNo * size,
      };
      const countRows = await db.query(
        WITH_LATEST + ' SELECT COUNT(*) AS total ' + FROM_WHERE,
        params,
      );
      const total = Number(countRows[0]['total']);
      if (total === 0) {
        throw new ApiError(404, 'PAYROLL_BASE_DATA_NOT_FOUND', '대상 범위에 급여 기준 데이터가 없습니다.');
      }
      const items = await db.query(
        WITH_LATEST + `
        SELECT e.employee_id AS "employeeId",
          e.name AS "employeeName",
          l.total_payment_amount AS "currentTotalPaymentAmount",
          l.total_deduction_amount AS "currentTotalDeductionAmount",
          l.net_pay_amount AS "currentNetPayAmount",
          (SELECT COALESCE(SUM(a.amount), 0) FROM payroll_item_amount a WHERE a.payroll_id = l.payroll_id) AS "currentItemAmount",
          COALESCE(l.total_payment_amount, 0) * (1 + CAST(:raiseRate AS numeric) / 100)
            + CAST(:stepChange AS numeric) * CAST(:stepAmount AS numeric) AS "simulatedTotalPaymentAmount",
          (COALESCE(l.total_payment_amount, 0) * (1 + CAST(:raiseRate AS numeric) / 100)
            + CAST(:stepChange AS numeric) * CAST(:stepAmount AS numeric))
            * (1 + CAST(:burdenRate AS numeric)) AS "simulatedLaborCost"
        ` + FROM_WHERE + `
        ORDER BY e.employee_id
        LIMIT :limit OFFSET :offset`,
        params,
      );
      return { items: items, page: pageNo, size: size, total: total };
    });
  }
}

