import { useState } from 'react';
import { call, Band, DataTable, Pager, Drawer, Form, Field, NumberInput, LookupSelect, Num, Tiles } from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr02118Page({ role, notify }: PageProps) {
  const [result, setResult] = useState<Page | undefined>(undefined);
  const [cond, setCond] = useState<Row>({});
  const [open, setOpen] = useState(false);
  const [raiseRate, setRaiseRate] = useState<number | string>('');
  const [stepChange, setStepChange] = useState<number | string>('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');

  async function run(body: Row, page: number) {
    const res = await call<Page>('POST', '/payroll-simulations/run', role, body, { page: page, size: SIZE });
    setResult(res);
    setCond(body);
  }

  async function submit() {
    if (raiseRate === '' && stepChange === '') {
      throw new Error('급여 인상률 또는 호봉 변경 단계 수를 입력하세요.');
    }
    const body: Row = {};
    if (raiseRate !== '') {
      body.raiseRate = raiseRate;
    }
    if (stepChange !== '') {
      body.stepChange = stepChange;
    }
    if (departmentId !== '') {
      body.departmentId = departmentId;
    }
    if (employeeId !== '') {
      body.employeeId = employeeId;
    }
    await run(body, 0);
    setOpen(false);
    notify('시뮬레이션을 실행했습니다.');
  }

  const rows = result ? result.items : [];
  const sumSimulated = rows.reduce((s, r) => s + Number(r.simulatedTotalPaymentAmount ?? 0), 0);
  const sumLabor = rows.reduce((s, r) => s + Number(r.simulatedLaborCost ?? 0), 0);

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>예상 결과 요약</h2>
        <Tiles
          items={[
            ['대상 인원', <Num value={result ? result.total : 0} />],
            ['예상 총 지급액 (현재 쪽)', <Num value={Math.round(sumSimulated)} />],
            ['예상 인건비 (현재 쪽)', <Num value={Math.round(sumLabor)} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>시뮬레이션 결과</h2>
        <Band total={result ? result.total : 0}>
          <button type="button" onClick={() => setOpen(true)}>시뮬레이션 실행</button>
        </Band>
        <DataTable
          columns={[
            { key: 'employeeName', label: '성명' },
            { key: 'currentTotalPaymentAmount', label: '현재 총 지급액', render: (r) => <Num value={r.currentTotalPaymentAmount} /> },
            { key: 'currentTotalDeductionAmount', label: '현재 총 공제액', render: (r) => <Num value={r.currentTotalDeductionAmount} /> },
            { key: 'currentNetPayAmount', label: '현재 실지급액', render: (r) => <Num value={r.currentNetPayAmount} /> },
            { key: 'currentItemAmount', label: '현재 급여 항목 금액', render: (r) => <Num value={r.currentItemAmount} /> },
            { key: 'simulatedTotalPaymentAmount', label: '조건 적용 후 예상 총 지급액', render: (r) => <Num value={Math.round(Number(r.simulatedTotalPaymentAmount ?? 0))} /> },
            { key: 'simulatedLaborCost', label: '조건 적용 후 예상 인건비', render: (r) => <Num value={Math.round(Number(r.simulatedLaborCost ?? 0))} /> },
          ]}
          rows={rows}
          empty="조건을 입력해 시뮬레이션을 실행하세요."
        />
        {result ? (
          <Pager
            page={result.page}
            size={result.size}
            total={result.total}
            onPage={(p) => {
              run(cond, p).catch((e) => notify(e instanceof Error ? e.message : '조회에 실패했습니다.'));
            }}
          />
        ) : null}
      </section>
      {open ? (
        <Drawer title="급여 시뮬레이션 조건" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="실행" note="실제 급여 데이터는 변경되지 않습니다.">
            <Field label="급여 인상률(%)">
              <NumberInput value={raiseRate} onChange={setRaiseRate} />
            </Field>
            <Field label="호봉 변경 단계 수">
              <NumberInput value={stepChange} onChange={setStepChange} />
            </Field>
            <Field label="대상 조직">
              <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} placeholder="전체" />
            </Field>
            <Field label="대상 임직원">
              <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체" />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
